shaderSource:
uniform float2 resolution;
uniform float tiltX;
uniform float tiltY;

float hash(float2 p) {
  return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

half4 main(float2 xy) {
  float2 uv = xy / max(resolution, float2(1.0, 1.0));
  float aspect = resolution.x / max(resolution.y, 1.0);
  float2 light = float2(0.32, 0.22) + float2(tiltX, tiltY) * 0.34;

  float2 cellUv = float2(uv.x * aspect, uv.y) * 5.2 + float2(tiltX, tiltY) * 0.55;
  float2 cell = floor(cellUv);
  float2 f = fract(cellUv);
  float n = hash(cell);
  float facet = smoothstep(0.08, 0.55, min(f.x, f.y) * min(1.0 - f.x, 1.0 - f.y) * 4.0);
  facet = mix(facet, 1.0 - facet, step(0.5, n));

  half3 deep = half3(0.35, 0.42, 0.55);
  half3 ice = half3(0.82, 0.90, 1.0);
  half3 edge = half3(0.55, 0.70, 0.95);
  half3 col = mix(deep, ice, facet * 0.85 + (1.0 - uv.y) * 0.2);
  col = mix(col, edge, abs(f.x - 0.5) * abs(f.y - 0.5) * 1.4);

  float2 d = uv - light;
  d.x *= aspect;
  float spec = exp(-dot(d, d) * 26.0);
  float bloom = exp(-dot(d, d) * 5.0);
  col += half3(1.0, 1.0, 1.0) * spec * 0.95;
  col += half3(0.7, 0.85, 1.0) * bloom * 0.25;

  float2 e = min(uv, 1.0 - uv);
  float rim = 1.0 - smoothstep(0.0, 0.1, min(e.x * aspect, e.y));
  col += half3(1.0, 1.0, 1.0) * rim * 0.35;

  float shade = smoothstep(0.0, 1.0, uv.y);
  col *= mix(1.08, 0.78, shade);

  return half4(col, 1.0);
}
